() => {
  // find buttons with the org data-range description
  const btns = Array.from(document.querySelectorAll('button')).filter(b => (b.getAttribute('title')||b.getAttribute('aria-label')||'').includes('数据范围') || (b.textContent||'').includes('全辖'));
  return btns.slice(0,6).map(b => ({ text: b.textContent.trim(), title: b.getAttribute('title')||b.getAttribute('aria-label')||'', parentText: b.parentElement ? b.parentElement.innerText.replace(/\n+/g,' | ').slice(0,120) : '' }));
}

() => {
  const rows = Array.from(document.querySelectorAll('table tbody tr'));
  return rows.map(r => Array.from(r.querySelectorAll('td')).map(td => td.innerText.replace(/\s+/g,' ').trim()));
}
